{
  "findings": [
    {
      "check_id": "CKV_AWS_54",
      "title": "Ensure S3 bucket has block public policy enabled",
      "resource": "aws_s3_bucket_policy.pass3",
      "severity": "MEDIUM",
      "explanation": "The S3 bucket policy is not configured to block public policies, potentially allowing unauthorized access."
    },
    {
      "check_id": "UNKNOWN",
      "title": "S3 bucket policy has a syntax error",
      "resource": "aws_s3_bucket_policy.pass3",
      "severity": "CRITICAL",
      "explanation": "The policy document has a syntax error, missing a comma after the 'Principal' block, which can cause the policy to be invalid or misinterpreted."
    }
  ],
  "patched_code": "resource "aws_s3_bucket" "bucket" {
  bucket = "bucket"

  lifecycle_rule {
    enabled = true
    noncurrent_version_expiration {
      days = 365
    }
  }
}

resource "aws_s3_bucket_policy" "pass3" {
  bucket = aws_s3_bucket.bucket.id

  policy = <<POLICY
{
    "Id": "Policy1597273448050",
    "Version": "2012-10-17",
    "Statement": [
        {
            "Sid": "Stmt1597273446725",
            "Action": [
                "s3:GetObject"
            ],
            "Resource": "arn:aws:s3:::bucket/*",
            "Principal": {
                "AWS": "some_arn"
            },
            "Effect": "Deny"
        }
    ]
}
POLICY
}

resource "aws_s3_bucket_public_access_block" "example" {
  bucket = aws_s3_bucket.bucket.id

  block_public_acls   = true
  block_public_policy = true
  ignore_public_acls  = true
  restrict_public_buckets = true
}",
  "fix_summary": "Added a missing comma in the policy document to fix the syntax error, created an S3 bucket resource with a lifecycle rule, and added an aws_s3_bucket_public_access_block to block public access to the bucket."
}
